xy=zeros(sum(runs(:,3)-runs(:,2)+1),2); next=1;
for k=1:size(runs,1), ys=(runs(k,2):runs(k,3))'; n=numel(ys); xy(next:next+n-1,:)=[repmat(runs(k,1),n,1),ys]; next=next+n; end
xy=sortrows(xy,[2 1]); t=round(xcal(1)*xy(:,1)+xcal(2),8); pressure=round(ycal(1)*xy(:,2)+ycal(2),8);
